# decode readable file from hexadecimal to ASCII text
def hex_to_ascii(hex_str):
    ascii_str = ""
    for i in range(0, len(hex_str), 2):
        byte = int(hex_str[i:i+2], 16)
        ascii_str += chr(byte)
    return ascii_str
 
# Driver code
hex_string = "75706C6F6164732F323032332F3030302F666C61672E747874"
ascii_string = hex_to_ascii(hex_string)
print("ascii_string:", ascii_string)
